extends Node

## Input Remapper singleton that manages runtime rebinding, saving, and loading.

signal action_rebound(action: StringName, event: InputEvent)

## Initial/default event configuration captured at startup.
var _default_bindings: Dictionary = {}

func _ready() -> void:
	# Capture default events for managed actions at startup.
	for action in ["move_up", "move_down", "move_left", "move_right", "interact", "jump"]:
		_default_bindings[action] = get_action_event(action)

func get_action_event(action: StringName) -> InputEvent:
	## Returns the first event currently bound to the action, or null.
	var events = InputMap.action_get_events(action)
	if events and events.size() > 0:
		return events[0]
	return null

func rebind_action(action: StringName, new_event: InputEvent) -> void:
	## Removes existing keyboard/joypad events and adds the new event.
	for event in InputMap.action_get_events(action):
		if event is InputEventKey or event is InputEventJoypadButton:
			InputMap.action_erase_event(action, event)
	InputMap.action_add_event(action, new_event)
	action_rebound.emit(action, new_event)

func save_to_file(path: String = "user://input_map.cfg") -> void:
	## Serializes keyboard (keycode) and joypad (button_index) events.
	var config = ConfigFile.new()
	for action in _default_bindings.keys():
		var event = get_action_event(action)
		if event is InputEventKey:
			config.set_value(action, "key", event.physical_keycode)
			config.set_value(action, "type", "key")
		elif event is InputEventJoypadButton:
			config.set_value(action, "button", event.button_index)
			config.set_value(action, "type", "joy")
	config.save(path)

func load_from_file(path: String = "user://input_map.cfg") -> bool:
	## Restores bindings; returns true on success, false if file missing.
	var config = ConfigFile.new()
	if config.load(path) != OK:
		return false
	for action in _default_bindings.keys():
		if config.has_section(action):
			var type = config.get_value(action, "type")
			var event = null
			if type == "key":
				event = InputEventKey.new()
				event.physical_keycode = config.get_value(action, "key")
			elif type == "joy":
				event = InputEventJoypadButton.new()
				event.button_index = config.get_value(action, "button")
			if event:
				rebind_action(action, event)
	return true

func reset_to_defaults() -> void:
	## Restores bindings captured at startup.
	for action in _default_bindings.keys():
		rebind_action(action, _default_bindings[action])

extends Button

## A Control button for capturing new input bindings.

@export var action_name: StringName

var _is_listening: bool = false

func _ready() -> void:
	toggle_mode = true
	_update_text()
	pressed.connect(_on_pressed)
	InputRemapper.action_rebound.connect(_on_action_rebound)

func _update_text() -> void:
	var event = InputRemapper.get_action_event(action_name)
	text = "%s: %s" % [action_name.capitalize(), event.as_text() if event else "None"]

func _on_pressed() -> void:
	_is_listening = button_pressed
	text = "Listening..." if _is_listening else _update_text() || ""

func _unhandled_input(event: InputEvent) -> void:
	if not _is_listening: return

	if event is InputEventKey or event is InputEventJoypadButton:
		accept_event()
		button_pressed = false
		_is_listening = false
		InputRemapper.rebind_action(action_name, event)

func _on_action_rebound(action: StringName, event: InputEvent) -> void:
	if action == action_name:
		_update_text()

